package com.dukaops.backend.sales;
import java.util.*; import org.springframework.data.domain.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param;
public interface SalesOrderRepository extends JpaRepository<SalesOrder,UUID>{ Optional<SalesOrder> findByTenant_IdAndIdempotencyKey(UUID tenantId,String key); @Query("select o from SalesOrder o where o.tenant.id=:tenantId and (:status is null or o.status=:status) and (:search is null or lower(o.customerName) like lower(concat('%',:search,'%')) or lower(o.idempotencyKey) like lower(concat('%',:search,'%'))) order by o.createdAt desc") Page<SalesOrder> search(@Param("tenantId")UUID tenantId,@Param("status")OrderStatus status,@Param("search")String search,Pageable pageable); }
